-- Release er-quality-1. Apply once AFTER bootstrap and identity-account 001..003.
-- Read-only probe executes with the migration owner's metadata visibility.
-- Grant API users EXECUTE on er_schema_ready, not CREATE/DROP/TRIGGER privileges.
CREATE TABLE er_schema_release (
 version varchar(64) CHARACTER SET ascii NOT NULL PRIMARY KEY,
 applied_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
) ENGINE=InnoDB;
DELIMITER $$
CREATE PROCEDURE er_schema_ready()
SQL SECURITY DEFINER
READS SQL DATA
BEGIN
 SELECT (
 EXISTS(SELECT 1 FROM er_schema_release WHERE version='er-quality-1')
 AND (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('audit_event','biennium','biennium_study_area','biennium_study_path','campus','class','class_subject','course_administration_event','course_edition','course_edition_campus','course_edition_formative_plan','er_schema_release','exam','exam_student','exam_submission','exam_violation','formative_module','formative_module_competency','formative_module_content','formative_plan','formative_plan_event','formative_plan_version','formative_unit','grade','identity_account_event','identity_account_state','identity_password_attempt','institution','institution_administration_event','institution_calendar_event','institution_calendar_import','institution_calendar_occupancy','institution_calendar_period','institution_calendar_settings','institution_class_event','institution_email_assignment','institution_email_event','institution_email_mutex','institution_email_policy','institution_email_reservation','institution_import_batch','institution_import_event','institution_import_external_reference','institution_import_item','institution_invitation','institution_lesson','institution_membership','institution_membership_event','institution_membership_role','institution_membership_security_state','institution_onboarding_event','institution_profile_acquisition','institution_provisioning','institution_recovery','institution_recovery_approval','institution_student_profile','institution_teacher_profile','mt3a_legacy_scope','platform_operation_nonce','question','question_option','student','student_class_transfer_event','student_enrollment','study_area','study_path','subject','submission_answer','submission_answer_option','teacher','user'))=71
 AND (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME IN ('administration_event_delete','administration_event_insert','administration_event_update','calendar_assignment_binding_bu','calendar_class_binding_bu','calendar_lesson_occupancy_au','cefp_delete','cefp_insert','cefp_update','class_event_delete','class_event_insert','class_event_update','email_assignment_delete','email_assignment_insert','email_assignment_override_reserve','email_assignment_reserve','email_assignment_update','email_event_delete','email_event_insert','email_event_update','email_policy_delete','email_policy_insert','email_policy_update','email_reservation_delete','email_reservation_insert','email_reservation_update','email_student_profile_link','email_teacher_profile_link','email_user_insert','email_user_update','fm_delete','fm_insert','fm_update','fmc_delete','fmc_insert','fmc_update','fmt_delete','fmt_insert','fmt_update','fp_delete','fp_insert','fp_update','fpe_delete','fpe_insert','fpe_update','fpv_delete','fpv_insert','fpv_update','fu_delete','fu_insert','fu_update','identity_account_event_no_delete','identity_account_event_no_update','identity_account_state_guard','import_batch_delete','import_batch_insert','import_batch_update','import_event_delete','import_event_insert','import_event_update','import_external_delete','import_external_insert','import_external_update','import_item_delete','import_item_insert','import_item_update','institution_calendar_event_bd','institution_calendar_event_bi','institution_calendar_event_bu','institution_calendar_import_bd','institution_calendar_import_bi','institution_calendar_import_bu','institution_calendar_occupancy_bd','institution_calendar_occupancy_bi','institution_calendar_occupancy_bu','institution_calendar_period_bd','institution_calendar_period_bi','institution_calendar_period_bu','institution_calendar_settings_bd','institution_calendar_settings_bi','institution_calendar_settings_bu','institution_lesson_bd','institution_lesson_bi','institution_lesson_bu','mt3a_audit_insert','mt3a_audit_update','mt3a_biennium_insert','mt3a_biennium_study_area_insert','mt3a_biennium_study_area_update','mt3a_biennium_study_path_insert','mt3a_biennium_study_path_update','mt3a_biennium_update','mt3a_class_insert','mt3a_class_subject_insert','mt3a_class_subject_update','mt3a_class_update','mt3a_exam_insert','mt3a_exam_student_insert','mt3a_exam_student_update','mt3a_exam_submission_insert','mt3a_exam_submission_update','mt3a_exam_update','mt3a_exam_violation_insert','mt3a_exam_violation_update','mt3a_grade_insert','mt3a_grade_update','mt3a_question_insert','mt3a_question_option_insert','mt3a_question_option_update','mt3a_question_update','mt3a_student_insert','mt3a_student_update','mt3a_study_area_insert','mt3a_study_area_update','mt3a_study_path_insert','mt3a_study_path_update','mt3a_subject_insert','mt3a_subject_update','mt3a_submission_answer_insert','mt3a_submission_answer_option_insert','mt3a_submission_answer_option_update','mt3a_submission_answer_update','mt3a_teacher_insert','mt3a_teacher_update','mt4_bsp_update','mt4_class_insert','mt4_class_update','mt4_course_edition_campus_update','mt4_course_edition_insert','mt4_course_edition_update','mt4_student_enrollment_insert','mt4_student_enrollment_update','mt4c_course_event_delete','mt4c_course_event_insert','mt4c_course_event_update','mt4c_enrollment_revision_insert','mt4c_enrollment_revision_update','mt5b_membership_delete_contract','mt5b_membership_identity_update','mt5b_membership_security_delete','mt5b_membership_security_insert','mt5b_membership_security_update','mt5b_role_identity_update','mt5b_role_security_delete','mt5b_role_security_insert','mt5b_security_delete','mt5b_security_insert','mt5b_security_update','mt5c_event_delete','mt5c_event_insert','mt5c_event_update','mt5c_invitation_delete','mt5c_invitation_insert','mt5c_invitation_update','mt5c_nonce_delete','mt5c_nonce_insert','mt5c_nonce_update','mt5c_provisioning_delete','mt5c_provisioning_insert','mt5c_provisioning_update','mt5d_event_delete','mt5d_event_insert','mt5d_event_snapshot_shape','mt5d_event_update','mt5gov_approval_delete','mt5gov_approval_insert','mt5gov_approval_update','mt5gov_institution_generation','mt5gov_institution_transition','mt5gov_recovery_delete','mt5gov_recovery_insert','mt5gov_recovery_update','profile_acquisition_insert','profile_acquisition_no_delete','profile_acquisition_no_update','staff_audit_delete','student_transfer_revision_update','transfer_event_delete','transfer_event_insert','transfer_event_update'))=180
 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='identity_account_state' AND COLUMN_NAME IN ('user_id','generation','display_name'))=3
 AND (SELECT COUNT(*) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME IN ('identity_account_state','identity_account_event','institution_profile_acquisition','identity_password_attempt') AND DELETE_RULE='RESTRICT')=7
 ) AS ready;
END$$
DELIMITER ;
INSERT INTO er_schema_release(version) VALUES('er-quality-1');
